import random

secreto = random.randint(1, 20)
intentos = 0
adivinado = False

while not adivinado and intentos < 5:
    numero = int(input("Adivina un número del 1 al 20: "))
    intentos = intentos + 1
    if numero < secreto:
        print("Más alto")
    elif numero > secreto:
        print("Más bajo")
    else:
        adivinado = True

if adivinado:
    if intentos == 1:
        print("¡Lo lograste en 1 intento!")
    else:
        print("¡Lo lograste en", intentos, "intentos!")
else:
    print("Perdiste, el número era", secreto)
